import { serverEnv } from '../../src/lib/config/server';
import { db } from '../../src/lib/db';

import { readWuerzburgManifest } from './wuerzburg-manifest';
import { seedWuerzburgInTransaction } from './wuerzburg-persistence';
import { seedWuerzburgAccounts } from './wuerzburg-accounts';

import type { SeedModule } from './helper/seed-types';

const seed: SeedModule = {
  name: 'Würzburg reference city',
  order: 10,
  async run(context) {
    if (serverEnv.NODE_ENV === 'production') {
      throw new Error('Reference city seeding is disabled in production');
    }
    const manifest = await readWuerzburgManifest();
    await seedWuerzburgAccounts(manifest);
    await db.transaction((tx) => seedWuerzburgInTransaction(tx, manifest));
    context.say(
      `Würzburg reference ready: ${manifest.pages.length} draft pages; Component Lab excluded from publication.`,
    );
  },
};

// eslint-disable-next-line import/no-default-export -- The existing seed discovery contract requires a default SeedModule export.
export default seed;

const fs = require('node:fs/promises');
const path = require('node:path');
const { chromium } = require('playwright');
const helpers = require(path.join(process.env.PW_SKILL_DIR, 'lib/helpers'));

const ROOT = path.resolve(__dirname, '../..');
const ARTIFACTS = path.join(ROOT, 'docs/würzburg/verification');

(async () => {
  const servers = await helpers.detectDevServers();
  process.stdout.write(`Detected servers: ${JSON.stringify(servers)}\n`);
  const target = process.env.TARGET_URL || 'http://localhost:3000';
  const browser = await chromium.launch({ headless: false });
  await fs.mkdir(ARTIFACTS, { recursive: true });
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
    const requests = [];
    const failures = [];
    page.on('request', (request) => {
      const url = new URL(request.url());
      if (url.protocol.startsWith('http') && url.origin !== new URL(target).origin) requests.push(`${url.origin}${url.pathname}`);
    });
    page.on('pageerror', (error) => failures.push(error.message));
    const response = await page.goto(`${target}/de/s/wuerzburg`, { waitUntil: 'domcontentloaded', timeout: 120_000 });
    await page.getByRole('heading', { level: 1 }).waitFor({ timeout: 60_000 });
    const summary = {
      capturedAt: new Date().toISOString(), url: page.url(), status: response.status(),
      title: await page.title(), headings: await page.getByRole('heading').allTextContents(),
      body: (await page.locator('body').innerText()).slice(0, 12_000),
      thirdPartyRequests: [...new Set(requests)], pageErrors: failures,
      horizontalOverflow: await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth),
    };
    await page.screenshot({ path: path.join(ARTIFACTS, 'home-desktop.png'), fullPage: true });
    await fs.writeFile(path.join(ARTIFACTS, 'browser-smoke.json'), `${JSON.stringify(summary, null, 2)}\n`);
    process.stdout.write(`${JSON.stringify(summary, null, 2)}\n`);
    if (summary.status !== 200 || failures.length > 0) process.exitCode = 1;
  } finally {
    await browser.close();
  }
})().catch((error) => { process.stderr.write(`${error.stack}\n`); process.exitCode = 1; });

const fs = require('node:fs/promises');
const path = require('node:path');
const { chromium } = require('playwright');
const helpers = require(path.join(process.env.PW_SKILL_DIR, 'lib/helpers'));

const ROOT = path.resolve(__dirname, '../..');
const ARTIFACTS = path.join(ROOT, 'docs/würzburg/verification');
const VIEWPORTS = [
  { name:'mobile',width:390,height:844 },
  { name:'tablet',width:768,height:1024 },
  { name:'desktop',width:1440,height:1000 },
  { name:'large-desktop',width:1920,height:1080 },
  { name:'reflow-320',width:320,height:800 },
];

(async () => {
  const servers = await helpers.detectDevServers();
  const origin = process.env.TARGET_URL || servers[0];
  if (!origin) throw new Error('No local server detected');
  const manifest = JSON.parse(await fs.readFile(path.join(ROOT,'data/seeds/wuerzburg.json'),'utf8'));
  const axe = await fs.readFile(require.resolve('axe-core/axe.min.js',{paths:[ROOT]}),'utf8');
  const browser = await chromium.launch({headless:false});
  const results = [];
  const thirdPartyRequests = new Set();
  await fs.mkdir(ARTIFACTS,{recursive:true});
  try {
    const page = await browser.newPage();
    page.on('request',(request)=>{
      const url = new URL(request.url());
      if (url.protocol.startsWith('http') && url.origin !== new URL(origin).origin) thirdPartyRequests.add(`${url.origin}${url.pathname}`);
    });
    for (const viewport of VIEWPORTS) {
      await page.setViewportSize({width:viewport.width,height:viewport.height});
      for (const item of manifest.pages.filter((candidate)=>candidate.path !== 'component-lab')) {
        const errors = [];
        const onError = (error) => errors.push(error.message);
        page.on('pageerror',onError);
        try {
          const url = `${origin}/de/s/wuerzburg${item.path ? `/${item.path}` : ''}`;
          const response = await page.goto(url,{waitUntil:'domcontentloaded',timeout:90_000});
          await page.getByRole('heading',{level:1}).waitFor({timeout:45_000});
          await page.locator('main').waitFor({timeout:15_000});
          const text = await page.locator('body').innerText();
          const overflow = await page.evaluate(()=>document.documentElement.scrollWidth > window.innerWidth);
          await page.addScriptTag({content:axe});
          const accessibility = await page.evaluate(async()=>{
            const report = await window.axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa','wcag22aa']}});
            return { violations:report.violations.map((violation)=>({id:violation.id,impact:violation.impact,description:violation.description,
              nodes:violation.nodes.map((node)=>({target:node.target,summary:node.failureSummary}))})), incomplete:report.incomplete.map((entry)=>entry.id) };
          });
          const result = {page:item.path || '/',viewport:viewport.name,status:response.status(),
            title:await page.title(),h1Count:await page.getByRole('heading',{level:1}).count(),
            mainCount:await page.getByRole('main').count(),horizontalOverflow:overflow,
            unavailableSections:(text.match(/Dieser Abschnitt ist vorübergehend nicht verfügbar/g)||[]).length,
            errors,...accessibility};
          results.push(result);
          if (['','karten','stadt-in-zahlen','buergerservice/termine'].includes(item.path) && ['desktop','reflow-320'].includes(viewport.name)) {
            await page.screenshot({path:path.join(ARTIFACTS,`${item.path.replaceAll('/','-') || 'home'}-${viewport.name}.png`),fullPage:true});
          }
          process.stdout.write(`${viewport.name} ${item.path || '/'}: HTTP ${result.status}; axe ${result.violations.length}; overflow ${overflow}; unavailable ${result.unavailableSections}\n`);
        } catch (error) {
          results.push({page:item.path || '/',viewport:viewport.name,error:error.message});
          process.stdout.write(`${viewport.name} ${item.path || '/'}: ${error.message.slice(0,180)}\n`);
        } finally {
          page.off('pageerror',onError);
        }
        await fs.writeFile(path.join(ARTIFACTS,'browser-suite.json'),`${JSON.stringify({capturedAt:new Date().toISOString(),origin,thirdPartyRequests:[...thirdPartyRequests],results},null,2)}\n`);
      }
    }
    const failed = results.filter((result)=>result.error || result.status !== 200 || result.h1Count !== 1 || result.mainCount !== 1 || result.horizontalOverflow || result.unavailableSections > 0 || result.violations?.length || result.errors?.length);
    process.stdout.write(`Completed ${results.length} page/viewport checks; ${failed.length} failures; ${thirdPartyRequests.size} third-party requests.\n`);
    if (failed.length || thirdPartyRequests.size) process.exitCode = 1;
  } finally {
    await browser.close();
  }
})().catch((error)=>{process.stderr.write(`${error.stack}\n`);process.exitCode=1;});

import { createHash } from 'node:crypto';
