const PAUSE_MS = 1_000;
const USER_AGENT = 'CivoReferenceCity/1.0 (public-data-contract-verification; no personal data)';
const sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));
const seen = new Map();
const executeFile = promisify(execFile);

// curl uses this Windows host's configured TLS trust; Node fetch cannot validate the session proxy.
async function request(url) {
  const { stdout } = await executeFile('curl.exe', [
    '--silent', '--show-error', '--location', '--max-redirs', '3', '--max-time', '20',
    '--max-filesize', String(MAX_BYTES), '--include', '--user-agent', USER_AGENT, url,
  ], { maxBuffer: MAX_BYTES + 100_000, timeout: TIMEOUT_MS + 5_000 });
  let rest = stdout;
  let header = '';
  while (rest.startsWith('HTTP/')) {
    const end = rest.indexOf('\r\n\r\n');
    if (end < 0) throw new Error('HTTP header boundary missing');
    header = rest.slice(0, end);
    rest = rest.slice(end + 4);
  }
  const lines = header.split('\r\n');
  const status = Number(lines.shift()?.split(' ')[1]);
  const headers = Object.fromEntries(lines.flatMap((line) => {
    const colon = line.indexOf(':');
    return colon < 0 ? [] : [[line.slice(0, colon).toLowerCase(), line.slice(colon + 1).trim()]];
  }).filter(([key]) => !['set-cookie', 'cookie'].includes(key)));
  return { status, headers, body: rest };
}

async function save(relative, value) {
  const target = new URL(relative, ROOT);
  await mkdir(new URL('./', target), { recursive: true });
  await writeFile(target, typeof value === 'string' ? value : `${JSON.stringify(value, null, 2)}\n`);
}

/** Captures bounded public responses, never request credentials or response cookies. */
async function capture(id, url) {
  if (seen.has(url)) return seen.get(url);
  const fetchedAt = new Date().toISOString();
  let response;
  try {
    response = await request(url);
    const { body, headers } = response;
    const bytes = Buffer.byteLength(body);
    const result = {
      id, url, fetchedAt, status: response.status,
      contentType: headers['content-type'] ?? null, headers, bytes,
      sha256: createHash('sha256').update(body).digest('hex'),
      verdict: response.status === 200 ? 'Fetched; license and schema review required' : 'Not Verified',
      body,
    };
    // The metadata file never includes the response body; dataset bodies are privacy-projected below.
    const metadata = { ...result };
    delete metadata.body;
    await save(`data/fixtures/${id}/response.meta.json`, metadata);
    seen.set(url, result);
    return result;
  } catch (error) {
    const result = { id, url, fetchedAt, status: response?.status ?? null, contentType: null,
      verdict: 'Not Verified', error: error instanceof Error ? error.message : 'Unknown fetch failure', body: null };
    await save(`data/fixtures/${id}/response.meta.json`, result);
    seen.set(url, result);
    return result;
  }
}

function parseJson(response) {
  try { return JSON.parse(response.body ?? 'null'); } catch { return null; }
}

function recordsOf(body) {
  if (Array.isArray(body)) return body;
  return body?.results ?? body?.records ?? body?.features ?? [];
}

// Full personal-record datasets are not copied. Projection records exactly which fields were omitted.
const PERSONAL_FIELD = /person|schulleit|ansprech|telefon|phone|e.?mail|kontaktperson|vorname|nachname|bearbeiter|redakteur|contact|mitglied|stolper|gedenk/i;
function privacyProjection(records) {
  const omittedFields = new Set();
  const project = (record) => {
    if (Array.isArray(record)) return record.map(project);
    if (record === null || typeof record !== 'object') return record;
    return Object.fromEntries(Object.entries(record).flatMap(([key, value]) => {
      if (PERSONAL_FIELD.test(key)) { omittedFields.add(key); return []; }
      return [[key, project(value)]];
    }));
  };
  return { records: records.map(project), omittedFields: [...omittedFields] };
}

function entityShapes(fields) {
  const names = fields.map((field) => field.name).join(' ');
  if (/geo_shape|geo_point|geometry|koordinat|geopoint/.test(names)) return ['Feature'];
  if (/datum|zeit|timestamp|date|jahr/.test(names) && /zahl|count|wert|value|anzahl|summe/.test(names)) return ['Series', 'Observation'];
  if (/stadtbezirk|stadtteil|wahl|einwohner|bevolker|haushalt/.test(names)) return ['Aggregate'];
  return ['Dataset'];
}

async function discoverCity() {
