    const safeFields = fields.filter((field) => !PERSONAL_FIELD.test(field.name)).map((field) => field.name);
    const endpoint = `${PORTAL}/api/explore/v2.1/catalog/datasets/${encodeURIComponent(id)}/records?limit=3${safeFields.length ? `&select=${encodeURIComponent(safeFields.join(','))}` : ''}`;
    let probe;
    if (!excluded) {
      if (previouslyCaptured) {
        try {
          const old = JSON.parse(await readFile(new URL(`wuerzburg-${id}/response.meta.json`, FIXTURES), 'utf8'));
