          note: 'Institutional/geographic/aggregate records only; no real personal contacts are retained. Raw response hash in response.meta.json refers to the fetched body before projection.',
        });
        await sleep(PAUSE_MS);
      }
    }
    const license = metadata.license ?? (terms.status === 200 && /Namensnennung/.test(terms.body ?? '') ? 'dl-de/by-2-0 (portal default; dataset-specific exceptions take precedence)' : null);
    entries.push({
      id: `wuerzburg-${id}`, name: metadata.title ?? id, publisher: metadata.publisher ?? 'Stadt Würzburg',
      url: endpoint, catalogUrl: `${PORTAL}/explore/dataset/${id}/`, accessType: 'Opendatasoft Explore REST v2.1',
      auth: 'none', license, licenseUrl: metadata.license_url ?? 'https://www.govdata.de/dl-de/by-2-0',
      attribution: 'Quelle: Stadt Würzburg – opendata.wuerzburg.de',
