      sample: excluded ? null : `data/fixtures/wuerzburg-${id}/sample.json`,
      entityShapes: entityShapes(fields), classification: 'inferred from actual schema; review mapping before use',
      grouping: { kind: 'source themes and keywords', themes: metadata.theme, tags: metadata.keyword, category: dataset.metas?.custom?.category ?? null },
      updateFrequency: metadata.update_frequency ?? 'Not specified', modified: metadata.modified, recordCount: metadata.records_count,
      coverage: metadata.bbox ?? metadata.geographic_reference ?? 'Würzburg portal; precise dataset extent requires review',
      time: { timezone: metadata.timezone, granularity: 'Not Verified', historyDepth: 'Not Verified' },
