        rateLimitReset: probe?.headers?.['x-ratelimit-reset'] ?? null, cacheControl: probe?.headers?.['cache-control'] ?? null },
      cors: probe?.headers?.['access-control-allow-origin'] ?? 'Not Verified', fields,
      resources: { attachments: dataset.attachments ?? [], alternativeExports: dataset.alternative_exports ?? [],
        exportDiscoveryUrl: `${PORTAL}/api/explore/v2.1/catalog/datasets/${id}/exports` },
      reliability: 'Single capture only; sustained availability Not Verified',
      verdict: excluded ? 'Skip (personal-record dataset)' : probe?.status === 200 && license ? 'Snapshot only' : 'Not Verified',
      reason: excluded ? 'No real personal data permitted in reference city' : 'Offline contract fixture; live binding requires reviewed field mapping, quota and freshness policy',
    });
    process.stdout.write(`${entries.length}/${datasets.length} ${id}: ${probe?.status ?? 'skipped'}\n`);
  }
  await save('data/sources/wuerzburg.sources.json', {
    schemaVersion: 1, capturedAt: new Date().toISOString(), catalogTotal: expected,
