  if (serverEnv.AUTH_DATABASE_URL !== undefined) {
    const client = new Client({ connectionString: serverEnv.AUTH_DATABASE_URL });
    await client.connect();
    try {
      await client.query('DELETE FROM "user" WHERE id = ANY($1::text[])', [ACCOUNTS]);
    } finally {
      await client.end();
    }
  }
  process.stdout.write('Removed only the Würzburg reference tenant and its exact fictional identity IDs.\n');
} finally {
  await disconnectDb();
}

import { readFile, writeFile } from 'node:fs/promises';

for (const locale of ['de','en']) {
  const target = new URL(`../../src/modules/component-platform/presentation/i18n/${locale}.json`, import.meta.url);
  const messages = JSON.parse(await readFile(target, 'utf8'));
  messages.componentPlatform.components.quickLinks.fields.placement = locale === 'de'
    ? { label:'Platzierung', options:{content:'Inhaltsliste',header:'Websitekopf',footer:'Websitefuß'} }
    : { label:'Placement', options:{content:'Content list',header:'Site header',footer:'Site footer'} };
  messages.componentPlatform.quickLinks.skipToContent = locale === 'de' ? 'Zum Hauptinhalt springen' : 'Skip to main content';
  await writeFile(target, `${JSON.stringify(messages,null,2)}\n`);
}

